sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?father ?fatherName ?deathDate WHERE {
  dbr:Badi'_al-Zaman_Mirza dbp:father ?father .
  OPTIONAL { ?father rdfs:label ?fatherName . FILTER (lang(?fatherName) = "en") }
  OPTIONAL { ?father dbp:deathDate ?deathDate . }
}
LIMIT 100

